  for (const s of (m.softwareSystems || [])) {
    containers += (s.containers || []).length;
    for (const c of (s.containers || [])) rels += (c.relationships || []).length;
    rels += (s.relationships || []).length;
  }
  for (const p of (m.people || [])) rels += (p.relationships || []).length;
}

return {
  validate: validate.status === "fulfilled" ? validate.value : validate.reason,
  parseOk: parse.status === "fulfilled",
  counts: { people, systems, containers, relationships: rels },
};

